/// <reference types="svelte" />
/// <reference types="vite/client" />

// Icon components generated by unplugin-icons (see vite.config.ts): `size` in px, plus any SVG attribute.
declare module "~icons/*" {
  import type { Component } from "svelte";
  import type { SVGAttributes } from "svelte/elements";
  const icon: Component<SVGAttributes<SVGSVGElement> & { size?: number | string }>;
  export default icon;
}
